    """chash 路由：哈希 UTF8(key) 取首个不小于它的令牌，越界回绕到环首。
    tokens/digests 非空（空环由调用方先报 STATE）。O(log N)，N 为令牌数。"""
    key_hash = int.from_bytes(
        hashlib.sha256(key.encode("utf-8")).digest(), "big"
    )
